// th15_s3_b7 — TH15 st03bs.ecl::BossCard4 (月符「紺色の狂夢」), source lines 1502-1571.
// The source timerReset at BossCard4 entry is this boss enemy's local frame 0; the 120-frame
// opening buffer and 4-frame startup margin are outside the source attack window.
// source_ref: st03bs.ecl.txt:1502-1571; dependency BossCard4_at:1573-1655.

const TIME_LIMIT: int = 3124;
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 38;

// TH15 type15 -> modern slot reuse; base radius matches (transcribe/th15/bullet-types.md).
const TH15_INVERT_RICE: int = 592;

const CARD4_COLOR_A: int = 5;  // BossCard4_at(0,5,...): etSprite color = B
const CARD4_COLOR_B: int = 3;  // BossCard4_at(1,3,...)

// Per-bullet EX closure: type256 OFFSCREEN(180) then WAIT(120) then type 0x200000 VELTIME
// (a=60, r=1.5/1.7, s=preserve angle). ANIM(1) birth stage is omitted per policy; its
// -4*velocity birth displacement is applied at fire time.
xformdef CARD4_BULLET(rate: fx) {
    offscreen_keep(180);
    wait(120);
    step_speed(rate, 60);
}

// Source BossCard4_at(A,B,C,D) async. A=shooter slot (one fire per tick, concurrency comes
// from the outer spawns); B=color; C/D = per-tick offset/velocity angular deltas in radians,
// pre-converted to BAM here (3deg=546, 10deg=1820, -1.5deg=-273, -20deg=-3641).
async sub boss_card4_at(color: int, c: int, d: int) {
    // %I = %ANGLE_PLAYER - pi/2, %J = %ANGLE_PLAYER + pi/2 (sampled once at async start).
    var base: int = aim_player() as int;
    var iang: int = base - 16384;
    var jang: int = base + 16384;
    var k: fx = 64fx;       // %K = 64 offset radius
    var cc: int = c;        // %C
    var dd: int = d;        // %D
    var knob: fx = 0.7fx;   // %N = diffF(1.1,0.7,0.7,0.7)
    var o: int = 400;       // %O = diffI(200,400,400,400)
    var w: int = 1;         // wait([-1]): Easy 2, else 1
    var rate: fx = 1.5fx;   // VELTIME r: E/N/H 1.5, Lunatic 1.7
    var r: int = global(GVAR_RANK);
    if r == RANK_EASY {
        cc = c * 2;         // !E: %C,%D doubled
        dd = d * 2;
        knob = 1.1fx;
        o = 200;
        w = 2;
    }
    if r == RANK_LUNATIC { rate = 1.7fx; }
    var iter: int = 0;
    while iter < o {
        // etAim(5) half-offset fixed ring with N=1: bullet direction = alpha + pi.
        var th: angle = (jang + 32768) as angle;
        // spawn at boss FINAL + etOffsetRad(%I,%K), minus ANIM birth displacement 4*speed(0.3).
        var bx: fx = $self_x + k * cos(iang as angle) - 1.2fx * cos(th);
        var by: fx = $self_y + k * sin(iang as angle) - 1.2fx * sin(th);
        _ = fire(TH15_INVERT_RICE, color, bx, by, 0.3fx, th, CARD4_BULLET(rate), none);
        iang = iang - cc;
        jang = jang + dd;
        k = k + knob;
        wait(w);
        iter = iter + 1;
    }
}

// Source Boss4 -> BossCard4 real boss. Entry (0,128); the segment's own movePosTime(60,4,0,144)
// (mode 4 = QUAD_OUT) carries it to (0,144). moveLimit(0,144,240,64) is inert for a static boss.
async sub boss_body() {
    set_invuln(65535);
    set_hurtbox(20fx);  // source setHurtbox(40,40): circular branch radius = 40/2
    set_hitbox(24fx);   // source setHitbox(48,48): circular branch radius = 48/2
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);           // source +60 label: set up loop counter
    var b: int = 1000;  // $B = 1000 (never drains before the 3000-frame timeout)
    loop {
        // One 520-frame source iteration: +60 spawn A, +80 extra (Hard/Lunatic),
        // +220 spawn B, +240 extra (Lunatic), +280 tail.
        wait(60);
        spawn boss_card4_at(CARD4_COLOR_A, 546, 1820);   // BossCard4_at(0,5,3deg,10deg)
        wait(20);
        if global(GVAR_RANK) >= RANK_HARD { spawn boss_card4_at(CARD4_COLOR_A, 546, 1820); }  // !HL
        wait(140);
        spawn boss_card4_at(CARD4_COLOR_B, -273, -3641); // BossCard4_at(1,3,-1.5deg,-20deg)
        wait(20);
        if global(GVAR_RANK) >= RANK_LUNATIC { spawn boss_card4_at(CARD4_COLOR_B, -273, -3641); } // !L
        wait(280);
        b = b - 1;
        if b <= 0 { break; }
    }
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 3000, 1, 0, 0, boss_body);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
